      }

      h1 {
        margin: 0 0 10px;
        font-size: 1.7rem;
        line-height: 1.15;
      }

      .description {
        margin: 0 0 24px;
        color: var(--muted);
        line-height: 1.55;
      }

      form {
        display: grid;
        gap: 20px;
      }

      .form-field {
        display: flex;
        gap: 12px;
        align-items: flex-start;
        padding: 16px;
        border: 1px solid var(--border);
        border-radius: 16px;
        background: #fbfdff;
      }

      .form-field input {
        margin-top: 3px;
        width: 18px;
        height: 18px;
        accent-color: var(--accent);
        flex: 0 0 auto;
      }

      .field-copy {
        display: grid;
        gap: 4px;
      }

      .field-copy label {
        font-weight: 600;
        line-height: 1.35;
      }

      .helper-text {
        margin: 0;
        color: var(--muted);
        font-size: 0.95rem;
        line-height: 1.45;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
      }

      button {
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.3rem;
        font: inherit;
        font-weight: 700;
        color: white;
        background: linear-gradient(180deg, var(--accent), var(--accent-hover));
        box-shadow: 0 10px 22px rgba(37, 99, 235, 0.24);
        cursor: pointer;
      }

