  <body>
    <main id="root" aria-live="polite"></main>

    <script>
      const h = (tag, attrs = {}, ...children) => ({ tag, attrs, children });

      const ConsentField = () =>
        h(
          "div",
          { class: "form-field" },
          h("input", {
            type: "checkbox",
            id: "terms",
            name: "terms",
            required: true,
            "aria-describedby": "terms-help",
          }),
          h(
            "div",
            { class: "field-copy" },
            h("label", { for: "terms" }, "I agree to the Terms of Use"),
            h(
              "p",
              { class: "helper-text", id: "terms-help" },
              "You must agree before submitting this form."
            )
          )
        );

      const App = () =>
        h(
          "section",
          { class: "card", "aria-labelledby": "title" },
          h("p", { class: "eyebrow" }, "Consent"),
          h("h1", { id: "title" }, "Confirm your agreement"),
          h(
            "p",
            { class: "description" },
            "Please review the terms and confirm your consent to continue."
          ),
          h(
            "form",
            { id: "consent-form" },
            ConsentField(),
            h(
              "div",
              { class: "actions" },
              h("button", { type: "submit" }, "Submit")
            )
          )
        );

      function render(node, container) {
        if (typeof node === "string") {
          return document.createTextNode(node);
        }

        const el = document.createElement(node.tag);
        Object.entries(node.attrs || {}).forEach(([key, value]) => {
          if (key.startsWith("on") && typeof value === "string") {
            el.setAttribute(key, value);
            return;
          }
          if (key === "for") {
            el.htmlFor = value;
            return;
          }
          el.setAttribute(key, value);
        });

        (node.children || []).forEach((child) => {
          el.appendChild(render(child));
        });

        if (container) container.appendChild(el);
        return el;
      }

      const app = App();
      render(app, document.getElementById("root"));
      document.getElementById("consent-form").addEventListener("submit", (event) => {
        event.preventDefault();
      });
    </script>
  </body>
